head.script:
scwin.onpageload = function() {
    //use data나 setJSON으로 넣으면 string타입으로 출력
    //스크립트에서 데이터 직접 추가 시 number타입으로 출력
    dataList1.setCellData(0, "col1", 12345678.12)
   // dataList1.setCellData(0, "col2", 123456789.12)

   // debugger;
    //console.log(dataList1.getFilteredColData('col1'));
    gridView2.setMaxLength("col1", "9.2");
    input1.setMaxLength("9.2");
	//gridView2.changeCurrency("col1", "euro",  "#.###,00");
    gridView2.changeCurrency({
      'colID': "col1",
      'type': "euro",
      'format': "#.###,00",
      'customModelFormatter': "scwin.euroCustomModelFormatter",
      'customModelUnformatter': "scwin.euroCustomModelUnformatter"
    });
    //gridView2.changeCurrency("col2", "tenge", "# ###-00")
    gridView2.changeCurrency({
      'colID': "col2",
      'type': "tenge",
      'format': "# ###,00",
      'customModelFormatter': "scwin.tengeCustomModelFormatter",
      'customModelUnformatter': "scwin.tengeCustomModelUnformatter"
    });

    //getCellData에서 string 타입으로 리턴(실데이터는 number)
    console.log(parseFloat(dataList1.getCellData(0,"col1"))+parseFloat(dataList1.getCellData(1,"col1"))) // 연산 결과 확인

   console.log(dataList1.getCellData(0,"col1")+dataList1.getCellData(1,"col1")) // 연산 결과 확인

};

 scwin.euroCustomModelFormatter = function(realData, formattedData) {
  realData = realData + "";
  return realData.replace(",", ".");
};
scwin.euroCustomModelUnformatter = function(realData, formattedData) {
  realData = realData + "";
  return realData.replace(".", ",");
};
scwin.tengeCustomModelFormatter = function(realData, formattedData) {
  realData = realData + "";
  return realData.replace(",", ".");
};
scwin.tengeCustomModelUnformatter = function(realData, formattedData) {
  realData = realData + "";
  return realData.replace(".", ",");
};
